package com.autoops.admin.controller;import com.autoops.user.entity.User;import com.autoops.user.repository.UserRepository;import com.autoops.execution.entity.Execution;import com.autoops.execution.repository.ExecutionRepository;import com.autoops.command.entity.CommandDefinition;import com.autoops.command.repository.CommandDefinitionRepository;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/admin")public class AdminController{private final UserRepository users;private final ExecutionRepository executions;private final CommandDefinitionRepository commands;public AdminController(UserRepository u,ExecutionRepository e,CommandDefinitionRepository c){users=u;executions=e;commands=c;}@GetMapping("/users")public List<User> users(){return users.findAll();}@GetMapping("/executions")public List<Execution> executions(){return executions.findAll();}@GetMapping("/commands")public List<CommandDefinition> commands(){return commands.findAll();}}
